#!/usr/bin/env bash
# Generated by scaffold-migration-prod — guarded production migration runner.
#
# Call this from your deploy AFTER the build step (it runs against the compiled
# dist/). It is SAFE to run on EVERY deploy: it applies pending migrations only
# once the `migrations` bookkeeping table exists (i.e. after the one-time
# baseline), and SKIPS otherwise — so it can never break a deploy.
#
# One-time adoption on a DB whose schema was built by auto-sync (synchronize):
#   npm run migration:baseline:prod   # records existing migrations, runs none
set -euo pipefail
cd "$(dirname "$0")/.."   # -> backend/

: "${DATABASE_URL:?DATABASE_URL is required}"

# Probe for the bookkeeping table. Any error (no connection, etc.) -> "absent",
# so uncertainty defaults to SKIP and the guard never aborts a deploy.
HAS_MIGRATIONS=$(node -e "const{Client}=require('pg');const c=new Client({connectionString:process.env.DATABASE_URL,connectionTimeoutMillis:8000});c.connect().then(()=>c.query(\"SELECT to_regclass('public.migrations') AS t\")).then(r=>console.log(r.rows[0].t===null?'absent':'present')).catch(()=>console.log('absent')).finally(()=>c.end())" 2>/dev/null | grep -Fx present || true)

if [ "$HAS_MIGRATIONS" = "present" ]; then
  echo "[migrate-prod] migrations table present -> applying pending migrations"
  npm run migration:run:prod
else
  echo "[migrate-prod] migrations table absent/unknown -> skipping"
  echo "[migrate-prod] run 'npm run migration:baseline:prod' ONCE to enable auto-migrations"
fi
